let libraryStage='all';
function scopeBadge(s){const m=s[11];return `<span class="scope-badge ${m.scope==='课标背诵'?'core':''}">${m.stage==='拓展'?'衔接':m.stage} · ${m.scope}</span>`}
function escapeHtml(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function scopeSource(m){return m.scope==='课标背诵'?curriculumSources[m.stage==='初中'?'junior':'high']:m.scope==='小学衔接'?curriculumSources.junior:curriculumSources.textbook;}
function readWork(id){const w=allWorks.find(w=>w.meta.id===id);if(!w)return;const {s,meta:m}=w,source=scopeSource(m);showModal(`<p class="eyebrow">${people[w.a].name} · ${m.kind} · 全文赏读</p><h2>${s[5]}</h2>${scopeBadge(s)}<p class="reader-meta">${s[0]} · ${s[1]} · ${m.role}</p><div class="reader-toolbar"><button id="hideText">遮住原文，自主背诵</button><button id="locateWork">在地图中查看 →</button></div><div id="readerText" class="reader-text ${m.kind==='散文'||m.kind==='赋'?'prose':''}">${s[6]}</div><div class="reader-notes"><h3>读懂这一篇</h3><p>${s[8]}</p><h3>赏读与复习</h3><p>${m.focus}</p><h3>想一想</h3><p>${s[10]}</p><h3>篇目依据与文本说明</h3><p><a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.label} ↗</a>${source.pages?' · '+source.pages:''}</p><p>${m.scope==='版本补充'?'此篇供旧版教材衔接与比较阅读，不列入本页课标覆盖统计。':m.scope==='教材补充'?'教材补充不等同于课标附录篇目；不同修订版、学制和地区的安排可能不同，请核对所用课本。':m.scope==='小学衔接'?'保留小学阶段作品作为衔接阅读，不计入初高中课标篇目统计。':'已按2025日常修订版附录核对作者与篇名。课标目录不等于所有地区的考试篇目清单。'}</p><p><a href="${m.textSource}" target="_blank" rel="noopener noreferrer">诗文原文参考汇编 ↗</a> · 正文采用通行简体文本。古典作品存在异文；考试书写、通假字与标点以当地教材和要求为准。赏读与讨论题为本站编写。</p><p>${m.dateNote||'采用通行系年，地点以现代坐标示意。'}</p></div>`);$('locateWork').onclick=()=>openWork(id);$('hideText').onclick=()=>{const hide=$('readerText').classList.toggle('text-hidden');$('readerText').setAttribute('aria-hidden',String(hide));$('hideText').textContent=hide?'显示原文，核对背诵':'遮住原文，自主背诵';};}
function filteredWorks(){const author=$('authorFilter').value,scope=$('scopeFilter').value,q=$('poemSearch').value.trim();return allWorks.filter(({s,a,meta:m})=>(libraryStage==='all'||m.stage===libraryStage)&&(author==='all'||a===+author)&&(scope==='all'||scope==='core'&&m.scope==='课标背诵'||scope==='extra'&&['教材补充','版本补充'].includes(m.scope)||scope==='bridge'&&m.scope==='小学衔接')&&(!q||[s[5],s[6],s[1],people[a].name,m.focus].some(t=>t.includes(q))));}
function renderLibrary(){const stages=[['all','全部篇目'],['初中','初中'],['高中','高中'],['拓展','衔接与拓展']];$('stageFilters').innerHTML=stages.map(([v,t])=>`<button data-stage="${v}" aria-pressed="${libraryStage===v}">${t}</button>`).join('');document.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>{libraryStage=el.dataset.stage;renderLibrary()});const works=filteredWorks();$('libraryCount').textContent=`找到 ${works.length} 篇 · 点击卡片读全文，或定位地图`;$('poemGrid').innerHTML=works.length?works.map(({s,a,meta:m})=>`<article class="poem-card">${scopeBadge(s)}<button class="card-title" data-read="${m.id}"><h3>${s[5]}</h3></button><div class="card-meta">${people[a].name} · ${m.kind} · ${s[0]}</div><p class="card-excerpt">${s[6].split('\n').filter(Boolean).slice(m.id==='ss-shuidiao'||m.id==='ss-ding'||m.id==='ss-huanxi'?1:0, m.id==='ss-shuidiao'||m.id==='ss-ding'||m.id==='ss-huanxi'?3:2).join('<br>')}</p><p class="card-place">⌖ ${s[1]} <span>${m.role}</span></p><div class="card-actions"><button data-read="${m.id}">全文赏读 ↗</button><button data-locate="${m.id}">${m.role==='地点待考'?'查看作品 →':'地图中查看 →'}</button></div></article>`).join(''):`<div class="empty-state"><h3>暂时没有匹配的篇目</h3><p>试试缩短关键词，或点击“重置筛选”。</p></div>`;document.querySelectorAll('[data-read]').forEach(el=>el.onclick=()=>readWork(el.dataset.read));document.querySelectorAll('[data-locate]').forEach(el=>el.onclick=()=>openWork(el.dataset.locate));}
function coverageHtml(stage){const works=allWorks.filter(w=>w.meta.scope==='课标背诵'&&(!stage||w.meta.stage===stage));return people.map((p,a)=>{const ws=works.filter(w=>w.a===a);return `<section class="coverage-author"><h3>${p.name} <small>${ws.length} 篇</small></h3>${ws.map(({s,meta:m})=>`<button data-coverage-work="${m.id}"><span>✓ ${s[5]}</span><small>${m.stage} · ${m.kind} · 全文已收录</small></button>`).join('')}</section>`}).join('');}
function showCoverage(stage){showModal(`<p class="eyebrow">对照目录 · 2026年10月21日核对</p><h2>${stage||'初高中'}课标覆盖清单</h2><p>仅统计李白、杜甫、苏轼。初中 8 篇（7 首诗词、1 篇古文），高中 11 篇（9 首诗词、2 篇古文）。以下均已收录全文；此处的“覆盖”不包括其他作者或所有可能出现的鉴赏材料。</p>${coverageHtml(stage)}<p><button id="openScopeFromList">查看核对依据和考试范围说明 ↗</button></p>`);document.querySelectorAll('[data-coverage-work]').forEach(el=>el.onclick=()=>readWork(el.dataset.coverageWork));$('openScopeFromList').onclick=showScope;}
function showScope(){showModal(`<p class="eyebrow">范围与依据 · 核对日期 2026年10月21日</p><h2>背诵有目录，鉴赏重能力</h2><p>本页围绕三位作者整理 37 篇作品。我们核对了初中与高中 2025 日常修订版课标附录中这三位作者的全部篇名：初中 8 篇，高中 11 篇；这不是整个中高考古诗文库的覆盖率。</p><h3>初中：课标附录的背诵基础</h3><p>《义务教育语文课程标准日常修订版（2022年版2025年修订）》附录1，7—9年级推荐60篇（段）。其中李白2篇、杜甫3篇、苏轼3篇，均已收录。<a href="${curriculumSources.junior.url}" target="_blank" rel="noopener noreferrer">凤溪中学公开课标 ↗</a> · <a href="${curriculumSources.junior.pdf}#page=64" target="_blank" rel="noopener noreferrer">PDF第64—66页 ↗</a>。</p><h3>高中：课标附录与教材相结合</h3><p>《普通高中语文课程标准日常修订版（2017年版2025年修订）》附录1推荐文言文32篇、诗词曲40首。其中三位作者共9首诗词，另含苏轼《赤壁赋》《石钟山记》，均已收录。<a href="${curriculumSources.high.url}" target="_blank" rel="noopener noreferrer">木里中学公开课标 ↗</a> · <a href="${curriculumSources.high.pdf}#page=60" target="_blank" rel="noopener noreferrer">PDF第60—63页 ↗</a>。</p><h3>为什么还要“教材补充”</h3><p>《峨眉山月歌》《春夜洛城闻笛》《渡荆门送别》《送友人》《江南逢李龟年》《石壕吏》《月夜忆舍弟》《卜算子》《浣溪沙》《定风波》等，按教材学习与比较阅读需要补入；《宣州谢朓楼饯别校书叔云》《秋兴》《咏怀古迹》用于版本衔接。目录与册次随修订、学制、地区而异，补充标签不表示已逐省核对当年考试范围。</p><p><a href="https://www.pep.com.cn/products/jc/czjks/201802/t20180209_1922672.shtml" target="_blank" rel="noopener noreferrer">人教社七上公开目录 ↗</a> · <a href="https://www.pep.com.cn/products/jc/czjks/201802/t20180209_1922680.shtml" target="_blank" rel="noopener noreferrer">七下公开目录 ↗</a> · <a href="https://www.pep.com.cn/products/jc/czjks/201802/t20180209_1922717.shtml" target="_blank" rel="noopener noreferrer">八上公开目录 ↗</a></p><h3>考试使用边界</h3><p>背诵推荐目录不是统一的考试题库。诗歌鉴赏可以考查课外作品；中考由各地组织，高考也有不同卷型与要求。正式备考需再核对所在省市、考试年份、所用教材和学校通知。本站不承诺覆盖所有历年或未来考题。</p><p>正文为古代公版原作，采用通行简体文本；异文和通假字以实际教材为准。作者真实行迹与诗中地点分开标注，不用文学想象推造旅行路线。</p>`);}
function initLibrary(){renderLibrary();$('scopeInfo').onclick=showScope;$('coverageList').onclick=()=>showCoverage();$('juniorCoverage').onclick=()=>showCoverage('初中');$('highCoverage').onclick=()=>showCoverage('高中');for(const id of ['authorFilter','scopeFilter'])$(id).onchange=renderLibrary;$('poemSearch').oninput=renderLibrary;$('clearFilters').onclick=()=>{libraryStage='all';$('authorFilter').value='all';$('scopeFilter').value='all';$('poemSearch').value='';renderLibrary()};}
